const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const json = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;
const uuid = (group: number, n: number) =>
  `00000000-0000-0000-${String(group).padStart(4, "0")}-${String(n).padStart(12, "0")}`;

/** Pre-check: seeded answers. Post-check: same student, a bit wiser (best answer on most questions). */
function mindsetAnswers(
  questions: MindsetQuestion[],
  seed: string,
  phase: "pre" | "post",
): MindsetAnswers {
  const rng = createRng(seed, "bots", phase === "pre" ? 1 : 2);
  const answers: MindsetAnswers = {};
  for (const question of questions) {
    const best = [...question.options].sort(
      (a, b) =>
        (b.points.plan ?? 0) + (b.points.know ?? 0) - ((a.points.plan ?? 0) + (a.points.know ?? 0)),
    )[0]!;
    const random = question.options[rng.int(0, question.options.length - 1)]!;
    answers[question.id] = phase === "post" && rng.chance(0.7) ? best.id : random.id;
  }
  return answers;
}

/** The decision log the app would have written for this game (actions, tosses, chapter end). */
function decisionLog(state: GameState, records: DecisionRecord[]): DecisionRecord[] {
  const ctx = (turn: number) => ({ chapterId: state.chapterId, turn });
  const out: DecisionRecord[] = [
    {
      type: "chapter_start",
      chapterId: state.chapterId,
      turn: 0,
      payload: { personaId: state.personaId },
    },
  ];
  for (const { turn, action } of state.actionLog) {
    const r = toDecisionLog(action, ctx(turn));
    if (r) out.push(r);
  }
  for (const toss of state.tosses) {
    out.push({
      type: "market_toss",
      chapterId: state.chapterId,
      turn: toss.turn,
      payload: { marketState: toss.marketState, independent: toss.independent },
    });
    if (toss.lifeEventId) {
      out.push({
        type: "life_event",
        chapterId: state.chapterId,
        turn: toss.turn,
        payload: { eventId: toss.lifeEventId },
      });
    }
  }
  return [...out, ...records];
}

function authUser(id: string, email: string, meta: Record<string, unknown>): string[] {
  return [
    `INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,`,
    `  raw_app_meta_data, raw_user_meta_data, confirmation_token, recovery_token, email_change_token_new,`,
    `  email_change, created_at, updated_at)`,
    `VALUES ('00000000-0000-0000-0000-000000000000', '${id}', 'authenticated', 'authenticated', ${q(email)},`,
    `  extensions.crypt(${q(DEMO_PASSWORD)}, extensions.gen_salt('bf')), NOW(),`,
    `  '{"provider":"email","providers":["email"]}'::jsonb, ${json(meta)}, '', '', '', '', NOW(), NOW());`,
    `INSERT INTO auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)`,
    `VALUES ('${id}', '${id}', ${json({ sub: id, email })}, 'email', NOW(), NOW(), NOW());`,
  ];
}

export function buildSeedSql(content: ContentBundle): string {
  const sql: string[] = [
    "-- Generated by scripts/seed.ts for the demo NGO & student cohort. Do not edit by hand:",
    "-- run `pnpm seed` to regenerate. Demo password for every account: " + DEMO_PASSWORD,
    "BEGIN;",
    "",
    "-- Clean previous demo data (cascades to profiles, codes, playthroughs, decisions…)",
    `DELETE FROM public.organizations WHERE id = '${ORG_ID}';`,
    `DELETE FROM auth.users WHERE id = '${ADMIN_ID}' OR id::text LIKE '00000000-0000-0000-0001-%';`,
    "",
    "-- 1. NGO admin login, organisation and profile",
    ...authUser(ADMIN_ID, ADMIN_EMAIL, {
      username: "hyderabad_admin",
      nickname: "Kavitha Facilitator",
    }),
    `INSERT INTO public.organizations (id, name, admin_user_id, settings)`,
    `VALUES ('${ORG_ID}', 'Hyderabad Youth Empowerment Trust', '${ADMIN_ID}', '{"codeExpiryDays": 30}'::jsonb);`,
    `INSERT INTO public.profiles (user_id, role, org_id, username, nickname, player_id, locale, has_recovery_email)`,
    `VALUES ('${ADMIN_ID}', 'ngo_admin', '${ORG_ID}', 'hyderabad_admin', 'Kavitha Facilitator', 'TL-ADMIN', 'en', true);`,
    ...GROUPS.map(
      (g) =>
        `INSERT INTO public.groups (id, org_id, name) VALUES ('${g.id}', '${ORG_ID}', ${q(g.name)});`,
    ),
    "",
  ];

  NICKNAMES.forEach((nickname, i) => {
    const n = i + 1;
    const userId = uuid(1, n);
    const playthroughId = uuid(3, n);
    const username = `student_${nickname.toLowerCase()}_${n}`.slice(0, 20);
    const seed = `demo-${n}`;
    const group = GROUPS[i % GROUPS.length]!;
    const codeStatus = i < 35 ? "active" : i < 38 ? "pending" : "expired";
    const last4 = String(1000 + i).slice(-4);

    const pre = mindsetAnswers(content.mindset.questions, seed, "pre");
    const preResult = scoreMindset(pre, content);
    const strategy = STRATEGIES[i % STRATEGIES.length]!;

    sql.push(
      `-- Student ${n}: ${nickname} (${preResult.personaId}, ${strategy}, code ${codeStatus})`,
    );
    const codeRow = [
      `INSERT INTO public.student_codes (id, org_id, code_hash, code_last4, label, group_id, status, expires_at, created_by, redeemed_by, redeemed_at)`,
      `VALUES ('${uuid(2, n)}', '${ORG_ID}', 'demo_hash_${n}', '${last4}', ${q(`${group.name} - seat ${n}`)}, '${group.id}', '${codeStatus}', ${codeStatus === "expired" ? "NOW() - interval '1 day'" : "NOW() + interval '30 days'"}, '${ADMIN_ID}', ${codeStatus === "active" ? `'${userId}'` : "NULL"}, ${codeStatus === "active" ? "NOW()" : "NULL"});`,
    ];
    if (codeStatus !== "active") {
      sql.push(...codeRow, "");
      return; // a seat that hasn't been redeemed yet has no student account
    }

    sql.push(
      // The login must exist before the redeemed code points at it.
      ...authUser(userId, `${username}@${STUDENT_DOMAIN}`, { username, nickname }),
      ...codeRow,
      `INSERT INTO public.profiles (user_id, role, org_id, username, nickname, avatar_id, player_id, locale, has_recovery_email)`,
      `VALUES ('${userId}', 'student', '${ORG_ID}', '${username}', ${q(nickname)}, 'avatar-${(i % 5) + 1}', 'TL-${String(10000 + i)}', 'en', false);`,
      `INSERT INTO public.group_members (group_id, student_user_id) VALUES ('${group.id}', '${userId}');`,
      `INSERT INTO public.mindset_responses (user_id, phase, answers, scores, persona_id, content_version, created_at)`,
      `VALUES ('${userId}', 'pre', ${json(pre)}, ${json(preResult.scores)}, '${preResult.personaId}', '${content.contentVersion}', NOW() - interval '14 days');`,
    );

    const { state, result } = playChapter(strategy, {
      content,
      personaId: preResult.personaId,
      seed,
      chapterId: "ch2-first-job",
    });
    sql.push(
      `INSERT INTO public.playthroughs (id, user_id, persona_id, seed, content_version, current_chapter_id, status, state)`,
      `VALUES ('${playthroughId}', '${userId}', '${preResult.personaId}', '${seed}', '${content.contentVersion}', 'ch2-first-job', 'completed', ${json(state)});`,
      `INSERT INTO public.chapter_results (playthrough_id, chapter_id, attempt, health_score, score_breakdown, report, passed)`,
      `VALUES ('${playthroughId}', 'ch2-first-job', 1, ${result.healthScore}, ${json(result.breakdown)}, ${json(result.report)}, ${result.passed});`,
      ...result.badgesEarned.map(
        (b) => `INSERT INTO public.badges_earned (user_id, badge_id) VALUES ('${userId}', '${b}');`,
      ),
    );
    for (const d of decisionLog(state, chapterResultRecords(result, state.turn))) {
      sql.push(
        `INSERT INTO public.decisions (playthrough_id, chapter_id, turn, type, payload) VALUES ('${playthroughId}', '${d.chapterId}', ${d.turn}, '${d.type}', ${json(d.payload)});`,
      );
    }

    // Most students who finished the chapter retook the Mindset Check (learning gain).
    if (i % 4 !== 3) {
      const post = mindsetAnswers(content.mindset.questions, seed, "post");
      const postResult = scoreMindset(post, content);
      sql.push(
        `INSERT INTO public.mindset_responses (user_id, phase, answers, scores, persona_id, content_version)`,
        `VALUES ('${userId}', 'post', ${json(post)}, ${json(postResult.scores)}, '${postResult.personaId}', '${content.contentVersion}');`,
      );
    }
    sql.push("");
  });

  sql.push("COMMIT;", "");
  return sql.join("\n");
}

// Run as a script: `pnpm seed`.
if (process.argv[1]?.endsWith("seed.ts")) {
  const loaded = loadContent();
  if (!loaded.ok) {
    console.error("content invalid — run pnpm content:validate");
    process.exit(1);
  }
  const outputPath = resolve(here, "../supabase/seed.sql");
  writeFileSync(outputPath, buildSeedSql(loaded.bundle), "utf-8");
  console.log(
    `✔ Demo seed written to ${outputPath} (password for all demo logins: ${DEMO_PASSWORD})`,
  );
}
